Correct Answer:
function throttle(fn, wait) {
  let previous = -Infinity;
  return function (...args) {
    const now = performance.now();
    if (now - previous >= wait) {
      previous = now;
      return fn.apply(this, args);
    }
  };
}
// O(1) wrapper time and retained state.

